import re
from typing import Dict, List, Optional, Tuple

def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    lines = text.splitlines()
    sections: Dict[str, Dict[str, str]] = {}
    current_section: Optional[str] = None
    current_key: Optional[str] = None
    current_value_lines: List[str] = []
    default_section: Dict[str, str] = {}
    seen_sections = False

    # Pattern for section headers
    section_pattern = re.compile(r'^\s*\[([^\]]+)\]\s*$')
    # Pattern for key-value pairs (first = or :)
    kv_pattern = re.compile(r'^\s*([^=:\s]+)(?:[=:]|(?=\s*[;#]))')
    # Pattern for inline comments (after whitespace)
    comment_pattern = re.compile(r'^\s*(.*?)\s*(?:[;#].*)?$')
    # Pattern for quoted values
    quoted_value_pattern = re.compile(r'^"(.*)"$')
    # Pattern for interpolation
    interpolation_pattern = re.compile(r'\$\{([^:}]+)(?::([^}]+))?\}')

    def resolve_interpolation(value: str, section: str, all_sections: Dict[str, Dict[str, str]]) -> str:
        def resolve(match: re.Match) -> str:
            key = match.group(1)
            other_section = match.group(2)
            if other_section is None:
                # Same section interpolation
                if section not in all_sections:
                    raise KeyError(f"Section '{section}' not found")
                if key not in all_sections[section] and section != 'DEFAULT':
                    # Check DEFAULT section
                    if 'DEFAULT' in all_sections and key in all_sections['DEFAULT']:
                        return all_sections['DEFAULT'][key]
                    raise KeyError(f"Key '{key}' not found in section '{section}'")
                return all_sections[section][key]
            else:
                # Other section interpolation
                if other_section not in all_sections:
                    raise KeyError(f"Section '{other_section}' not found")
                if key not in all_sections[other_section]:
                    raise KeyError(f"Key '{key}' not found in section '{other_section}'")
                return all_sections[other_section][key]

        # Track visited sections to detect cycles
        visited = set()
        def resolve_recursive(value: str, section: str) -> str:
            if (section, value) in visited:
                raise ValueError("Interpolation cycle detected")
            visited.add((section, value))
            try:
                return interpolation_pattern.sub(resolve, value)
            finally:
                visited.remove((section, value))

        return resolve_recursive(value, section)

    for line_num, line in enumerate(lines, 1):
        stripped_line = line.strip()
        if not stripped_line or stripped_line.startswith((';', '#')):
            continue

        # Check for section header
        section_match = section_pattern.match(line)
        if section_match:
            section_name = section_match.group(1)
            if current_section is not None and current_key is not None:
                raise ValueError(f"Key line before section header at line {line_num}")
            if section_name == 'DEFAULT':
                current_section = None
                default_section = {}
            else:
                current_section = section_name
                if current_section not in sections:
                    sections[current_section] = {}
                    # Inherit from DEFAULT
                    if 'DEFAULT' in sections:
                        sections[current_section].update(sections['DEFAULT'])
                    else:
                        sections[current_section].update(default_section)
            seen_sections = True
            current_key = None
            current_value_lines = []
            continue

        # Check for key-value line
        if current_section is None and not seen_sections:
            raise ValueError(f"Key line before any section header at line {line_num}")

        # Check for continuation line
        if line.startswith((' ', '\t')):
            if current_key is None:
                raise ValueError(f"Continuation line without preceding key at line {line_num}")
            current_value_lines.append(line.strip())
            continue

        # Parse key-value pair
        kv_match = kv_pattern.match(line)
        if not kv_match:
            raise ValueError(f"Malformed line at line {line_num}")

        key = kv_match.group(1).strip().lower()
        rest = line[kv_match.end():].strip()

        # Handle inline comments
        comment_pos = -1
        for i, c in enumerate(rest):
            if c in (';', '#') and (i == 0 or rest[i-1].isspace()):
                comment_pos = i
                break
        if comment_pos != -1:
            rest = rest[:comment_pos].strip()

        # Handle quoted value
        if rest.startswith('"') and rest.endswith('"'):
            value = rest[1:-1]
            # Check for unescaped quotes inside (simple implementation)
            if value.count('"') % 2 != 0:
                raise ValueError(f"Unmatched quote in value at line {line_num}")
        else:
            # Split on first = or :
            value_parts = rest.split('=', 1)
            if len(value_parts) == 1:
                value_parts = rest.split(':', 1)
            if len(value_parts) != 2:
                raise ValueError(f"Missing value for key '{key}' at line {line_num}")
            value = value_parts[1].strip()

        # Handle continuation lines
        if current_key is not None:
            # This is a continuation of the previous key
            current_value_lines.append(value)
            value = '\n'.join(current_value_lines)
            current_value_lines = []
        else:
            current_key = key

        # Store the value
        if current_section is None:
            default_section[key] = value
        else:
            sections[current_section][key] = value

        current_key = None

    # Resolve all interpolations
    for section in list(sections.keys()):
        if section == 'DEFAULT':
            continue
        for key in list(sections[section].keys()):
            try:
                sections[section][key] = resolve_interpolation(sections[section][key], section, sections)
            except (KeyError, ValueError) as e:
                raise ValueError(f"Error resolving interpolation in section '{section}', key '{key}': {e}") from e

    # Remove DEFAULT section from output
    if 'DEFAULT' in sections:
        del sections['DEFAULT']

    return sections
