import collections
import time

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._cache = collections.OrderedDict()
        self._stats = {
            "hits": 0,
            "misses": 0,
            "evictions": 0,
            "expirations": 0
        }

    def _clean_expired(self):
        now = self.clock()
        expired_keys = []
        for key, (value, expiry) in self._cache.items():
            if now >= expiry:
                expired_keys.append(key)
        for key in expired_keys:
            del self._cache[key]
            self._stats["expirations"] += 1

    def _evict_if_needed(self):
        if self.capacity > 0 and len(self._cache) >= self.capacity:
            self._cache.popitem(last=False)
            self._stats["evictions"] += 1

    def put(self, key, value):
        if self.capacity == 0:
            return

        now = self.clock()
        expiry = now + self.ttl

        if key in self._cache:
            # Update existing entry
            self._cache.move_to_end(key)
            self._cache[key] = (value, expiry)
        else:
            # Insert new entry
            self._clean_expired()
            if len(self._cache) >= self.capacity:
                self._evict_if_needed()
            self._cache[key] = (value, expiry)

    def get(self, key, default=None):
        if self.capacity == 0:
            self._stats["misses"] += 1
            return default

        now = self.clock()
        if key in self._cache:
            value, expiry = self._cache[key]
            if now < expiry:
                # Hit
                self._cache.move_to_end(key)
                self._stats["hits"] += 1
                return value
            else:
                # Expired
                del self._cache[key]
                self._stats["expirations"] += 1
        else:
            # Miss
            self._stats["misses"] += 1
        return default

    def __len__(self):
        now = self.clock()
        return sum(1 for (_, expiry) in self._cache.values() if now < expiry)

    def stats(self):
        return self._stats.copy()
