def parse_duration(s: str) -> int:
    if not s.strip():
        raise ValueError("Empty or blank string")

    parts = []
    current_part = []
    i = 0
    n = len(s)

    while i < n:
        c = s[i]
        if c.isdigit() or c == '.':
            current_part.append(c)
            i += 1
        elif c in 'hmsHMS':
            if not current_part:
                raise ValueError("Number without a unit")
            if '.' in current_part:
                raise ValueError("Decimals not allowed")
            parts.append((''.join(current_part), c.lower()))
            current_part = []
            i += 1
        elif c.isspace():
            i += 1
        else:
            raise ValueError(f"Unknown character: {c}")

    if current_part:
        raise ValueError("Number without a unit")

    if not parts:
        raise ValueError("No valid duration parts found")

    units = []
    values = []
    for value, unit in parts:
        try:
            num = int(value)
        except ValueError:
            raise ValueError(f"Invalid number: {value}")

        if unit in units:
            raise ValueError(f"Repeated unit: {unit}")
        units.append(unit)
        values.append(num)

    if units != ['h', 'm', 's']:
        raise ValueError("Units must appear in order h, m, s")

    total_seconds = 0
    for i, unit in enumerate(units):
        if unit == 'h':
            total_seconds += values[i] * 3600
        elif unit == 'm':
            total_seconds += values[i] * 60
        elif unit == 's':
            total_seconds += values[i]

    return total_seconds
