def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    unique_sorted = sorted(set(nums))
    result = []
    start = unique_sorted[0]
    prev = start

    for num in unique_sorted[1:]:
        if num == prev + 1:
            prev = num
        else:
            if start == prev:
                result.append(str(start))
            elif prev == start + 1:
                result.append(f"{start},{prev}")
            else:
                result.append(f"{start}..{prev}")
            start = num
            prev = num

    # Handle the last range
    if start == prev:
        result.append(str(start))
    elif prev == start + 1:
        result.append(f"{start},{prev}")
    else:
        result.append(f"{start}..{prev}")

    return ",".join(result)
